<!doctype html><html><head><meta charset="utf-8"><title>{{ $post->exists?'Edit':'Add' }} Blog</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f4ef;font:15px Arial;color:#17243a}.wrap{max-width:1100px;margin:35px auto;background:#fff;padding:30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.full{grid-column:1/-1}label{display:block;font-weight:bold;margin-bottom:8px}input,select,textarea{width:100%;box-sizing:border-box;padding:13px;border:1px solid #d4d4d4;border-radius:6px;font:inherit}textarea{min-height:110px}.editor{border:1px solid #ccc;border-radius:6px}.tools{padding:10px;background:#f3f3f3;border-bottom:1px solid #ddd}.tools button{margin-right:5px;padding:7px 10px}.editable{min-height:380px;padding:18px;outline:0}.checks{display:flex;gap:25px;flex-wrap:wrap}.checks label{font-weight:normal}.save{padding:14px 22px;background:#f5ad00;border:0;font-weight:bold;border-radius:6px}.back{float:right}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}}
