ref="{{ route('admin.attorneys.create') }}"><x-admin-icon name="user"/>Add Attorney</a><a href="{{ route('admin.attorneys.details') }}"><x-admin-icon name="users"/>Attorney Detail Page</a><a href="{{ route('admin.capabilities.index') }}"><x-admin-icon name="chart"/>Capabilities</a><a href="{{ route('admin.capabilities.pages') }}"><x-admin-icon name="file"/>Capability Pages</a><a href="{{ route('admin.contact-settings.edit') }}"><x-admin-icon name="mail"/>Contact Us</a><p class="resource-heading">INSIGHTS &amp; RESOURCES</p><div class="resource-links"><a class="active" href="{{ route('admin.blog.index') }}"><x-admin-icon name="edit"/>Blog</a><a href="{{ url('/admin/blog?type=case_study') }}"><x-admin-icon name="file"/>Case Study</a><a href="{{ url('/admin/blog?type=insight') }}"><x-admin-icon name="bulb"/>Insight</a></div></nav></aside><main class="wrap"><a class="back" href="{{ route('admin.blog.index') }}">← Back</a><h1>{{ $post->exists ? 'Edit ' : 'Add ' }}{{ $contentType === 'case_study' ? 'Case Study' : ($contentType === 'insight' ? 'Insight' : 'Blog Post') }}</h1><form method="post" action="{{ $post->exists?route('admin.blog.update',$post):route('admin.blog.store') }}" enctype="multipart/form-data">@csrf<input type="hidden" name="content_type" value="{{ old('content_type',$post->content_type ?: 'blog') }}"> @if($post->exists) @method('PUT') @endif<div class="grid"><div><label>Title / Name *</label><input name="title" required value="{{ old('title',$post->title) }}"></div><div><label>URL Slug</label><input name="slug" value="{{ old('slug',$post->slug) }}"></div><div><label>Category</label><input name="category" placeholder="Legal News, Corporate, Employment..." value="{{ old('category',$post->category) }}"></div><div><label>Publish Date</label><input type="date" name="published_at" value="{{ old('published_at',optional($post->published_at)->format('Y-m-d')) }}"></div><div><label>Status</label><select name="status"><option value="draft" {{ old('status',$post->status)==='draft' ? 'selected' : '' }}>Draft</option><option value="published" {{ old('status',$post->status)=== 'published' ? 'selected' : '' }}>Published</option></select></div><div><label>Featured Image</label>@if($post->featured_image)<div class="current-image"><img src="{{ $post->featured_image_url }}" alt="Current featured image"><small>Current image is saved. Choose a new file only if you want to replace it.</small></div>@endif<input type="file" name="featured_image" accept="image/*"> @if($contentType === 'insight')<label style="display:block;margin-top:12px">Home Page Image (separate from Featured Image)</label>@if($post->home_image)<div class="current-image"><img src="{{ $post->home_image_url }}" alt="Current home page image"></div>@endif<input type="file" name="home_image" accept="image/*">@endif</div><div class="full"><label>{{ $contentType === 'case_study' ? 'Case Study Content' : ($contentType === 'insight' ? 'Insight Content' : 'Article Content') }}</label><textarea id="article-editor" name="content">{{ old('content',$post->content) }}</textarea></div><div class="full"><h2>SEO & Search Visibility</h2></div><div><label>Meta Title</label><input name="meta_title" value="{{ old('meta_title',$post->meta_title) }}"></div><div><label>Robots</label><select name="robots"><option>index, follow</option><option>noindex, nofollow</option><option>index, nofollow</option></select></div><div class="full"><label>Meta Description</label><textarea name="meta_description">{{ old('meta_description',$post->meta_description) }}</textarea></div><div class="full"><label>Meta Keywords / Tags</label><input name="meta_keywords" value="{{ old('meta_keywords',$post->meta_keywords) }}"></div><div class="full"><label>Schema JSON-LD</label><textarea name="schema_json" placeholder="Optional valid JSON-LD">{{ old('schema_json',$post->schema_json) }}</textarea></div><div class="full"><h2>Visibility & Linking</h2><div class="visibility-options"><label class="visibility-option"><input type="checkbox" name="show_on_home" value="1" {{ old('show_on_home',$post->show_on_home) ? 'checked' : '' }}><span>{{ $contentType === 'insight' ? 'Featured image show on home page' : 'Show on home page' }}</span></label></div></div><div class="full"><label>Show on selected attorney detail page(s)</label><p class="point-help">Tick an attorney to show this post in their Insights And News section.</p><div class="visibility-options">@foreach($attorneys as $attorney)<label class="visibility-option"><input type="checkbox" name="attorney_ids[]" value="{{ $attorney->id }}" {{ $post->attorneys->contains($attorney) ? 'checked' : '' }}><span>{{ $attorney->name }}</span></label>@endforeach</div></div><div class="full"><label>Show on selected capability page(s)</label><p class="point-help">Tick a capability to show this post in its Insights And News section.</p><div class="visibility-options">@foreach($capabilities as $capability)<label class="visibility-option"><input type="checkbox" name="capability_ids[]" value="{{ $capability->id }}" {{ $post->capabilities->contains($capability) ? 'checked' : '' }}><span>{{ $capability->title }}</span></label>@endforeach</div></div></div><br><button class="save">Save {{ $contentType === 'case_study' ? 'Case Study' : ($contentType === 'insight' ? 'Insight' : 'Blog Post') }}</button></form></main><script src="https://cdn.jsdelivr.net/npm/tinymce@7.9.1/tinymce.min.js" referrerpolicy="origin"></script><script>tinymce.init({selector:"#article-editor",base_url:"https://cdn.jsdelivr.net/npm/tinymce@7.9.1",suffix:".min",height:520,menubar:"file edit view insert format tools table help",plugins:"advlist autolink lists link image charmap preview anchor searchreplace visualblocks code fullscreen insertdatetime media table wordcount",toolbar:"undo redo | blocks fontfamily fontsize | bold italic underline strikethrough forecolor backcolor | alignleft aligncenter alignright alignjustify | bullist numlist outdent indent | link image media table | code fullscreen",content_style:"body{font-family:Arial,sans-serif;font-size:15px;line-height:1.6;padding:12px}"});document.querySelector("form").addEventListener("submit",()=>tinymce.triggerSave());</script></body></html>